#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
    Node(int val) : data(val), next(NULL) {}
};

// Insert at beginning - O(1)
Node* insertAtHead(Node* head, int val) {
    Node* newNode = new Node(val);
    newNode->next = head;
    return newNode;
}

// Insert at end - O(n)
void insertAtTail(Node* head, int val) {
    Node* newNode = new Node(val);
    Node* temp = head;
    while (temp->next != NULL)
        temp = temp->next;
    temp->next = newNode;
}

// Delete a node with given value - O(n)
Node* deleteNode(Node* head, int val) {
    if (head == NULL) return NULL;
    if (head->data == val) {
        Node* temp = head->next;
        delete head;
        return temp;
    }
    Node* temp = head;
    while (temp->next != NULL && temp->next->data != val)
        temp = temp->next;
    if (temp->next != NULL) {
        Node* toDelete = temp->next;
        temp->next = temp->next->next;
        delete toDelete;
    }
    return head;
}

// Search - O(n)
bool search(Node* head, int val) {
    Node* temp = head;
    while (temp != NULL) {
        if (temp->data == val) return true;
        temp = temp->next;
    }
    return false;
}

// Reverse - O(n)
Node* reverse(Node* head) {
    Node* prev = NULL;
    Node* curr = head;
    while (curr != NULL) {
        Node* nxt = curr->next;
        curr->next = prev;
        prev = curr;
        curr = nxt;
    }
    return prev;
}

int main() {
    Node* head = NULL;
    head = insertAtHead(head, 30);
    head = insertAtHead(head, 20);
    head = insertAtHead(head, 10);
    // 10 -> 20 -> 30

    insertAtTail(head, 40);
    // 10 -> 20 -> 30 -> 40

    head = deleteNode(head, 20);
    // 10 -> 30 -> 40

    cout << "Search 30: " << search(head, 30) << endl; // 1

    head = reverse(head);
    // 40 -> 30 -> 10

    Node* temp = head;
    while (temp) { cout << temp->data << " "; temp = temp->next; }
    // Output: 40 30 10
    return 0;
}

